def inferType(s):
	# Normalize case for boolean check
	if isinstance(s, basestring):
		val = s.strip().lower()
		if val == 'true' or val == 'false': return 'bool'

		# Try to convert to int
		try:
			intVal = int(s)
			return 'int'
		except ValueError:
			pass

		# Try to convert to float
		try:
			floatVal = float(s)
			return 'float'
		except ValueError:
			pass

		# If all else fails
		return 'string'
	else:
		return type(s).__name__  # non-string input

if self.view.custom.userAction.canUpdate:
	configInfo = dict(self.props.data[event.row])

	if configInfo['configTypeName'] in ('db', 'tag'):
		system.perspective.sendMessage('showInfoToast', {'message': 'These values should not be edited. Trust us on this.'})
	elif configInfo['configName'] in ('endScheduledProductionRuns', 'editPastScheduleEvents', 'shiftTimeOnly', 'intelligentScheduling'):
		if inferType(event.value) != 'bool':
			system.perspective.sendMessage('showInfoToast', {'message': 'Value must be a boolean (0 or 1).'})
	elif configInfo['configName'] in ('shiftCalendarStartDay', 'operationCalendarStartDay'):
		if inferType(event.value) != 'int' or (event.value < 0 or event.value > 6):
			system.perspective.sendMessage('showInfoToast', {'message': 'Value must be a integer in range (0 to 6).'})

	configInfo['configValue'] = event.value
	retVal, msg = system.kanoa.config.saveConfig(configInfo, self.view.custom.security.userId)
	system.perspective.sendMessage('configUpdate', {})	#Updates the header view
	if msg: system.perspective.sendMessage('showFailerToast', {'message': 'Failed to update the configuration. %s'%msg})
	else: system.perspective.sendMessage('showSuccessfulToast', {'message': 'Configuration has been updated'})		

self.view.refreshBinding("custom.data")
self.props.selection.selectedRow = None	
self.props.selection.selectedCol = None	

return
